window.EmbeddedProjectMedia = {
  "assets/kitchen_exterior.jpg": "",
  "assets/evacuation_plan_b52.jpg": ""
};

// ============================================================================
// محرك تصدير العرض التقديمي إلى PowerPoint (.pptx) — مطبخ العزيزية المركزي 52
// كاتب OOXML يدوي بلا مكتبات خارجية (يعمل من file:// دون إنترنت).
// الشرائح: غلاف ← نظرة عامة ← الخريطة الكروكية ← المخطط الهندسي ←
//          لكل قسم: نظرة عامة + الأصول (4 لكل شريحة) + الكوادر (3 لكل شريحة) ← ختام.
// معايير: 16:9، نصوص أصلية قابلة للتعديل، RTL، خط آمن (Segoe UI)،
//          العناوين ≥ 28pt، الأجسام ≥ 14pt، التسميات ≥ 12pt، نص بديل لكل صورة.
// ============================================================================

window.PptxExporter = (function () {
  "use strict";

  // --------------------------------------------------------------------------
  // 1. ثوابت التصميم (مأخوذة من :root في css/styles.css)
  // --------------------------------------------------------------------------
  const C = {
    navy950: "0B1B30", navy900: "102A47", navy800: "17375C", navy700: "1E3A5F",
    navy600: "2E5A88", navy200: "C9D8EA", navy100: "E3EBF5", navy50: "F1F5FA",
    gold700: "8A5416", gold600: "A8691F", gold500: "C4852C", gold300: "E6B96D", gold100: "F8EBD3",
    ink: "1B2433", ink2: "434F63", ink3: "5B6577",
    bg: "F2F4F8", surface: "FFFFFF", surface2: "F8FAFC", line: "E3E8EF", line2: "CFD7E2",
    ok: "157347", okBg: "E8F5EE", okLine: "B9E0C9",
    warn: "946011", warnBg: "FDF3DE", warnLine: "F0D9A3",
    bad: "B42318", badBg: "FDECEA", badLine: "F5C2BD",
    info: "1E5A99", infoBg: "E8F1FB", infoLine: "BCD5F0"
  };
  const FONT = "Segoe UI";
  const SZ = { title: 28, cover: 34, h2: 18, body: 14, label: 12, kpi: 28 }; // بالنقاط
  const SLD_W_IN = 13.333, SLD_H_IN = 7.5;
  const SLD_W = 12192000, SLD_H = 6858000;
  const M = 0.4; // الهامش الجانبي بالبوصة
  const CONTENT_W = SLD_W_IN - 2 * M;
  const ASSETS_PER_SLIDE = 4;
  const STAFF_PER_SLIDE = 3;

  const CATEGORY_ORDER = [
    "الإنتاج والطبخ", "التبريد والتجميد", "التحضير والتقطيع",
    "المستودعات والتخزين", "التحكم والمرافق الفنية", "الإدارة والخدمات"
  ];
  const CATEGORY_COLORS = {
    "الإنتاج والطبخ": "A8691F",
    "التبريد والتجميد": "2E5A88",
    "التحضير والتقطيع": "B84A58",
    "المستودعات والتخزين": "B86B35",
    "التحكم والمرافق الفنية": "9B3B3B",
    "الإدارة والخدمات": "4A5568"
  };
  // نفس وسيلة الإيضاح المعروضة في صفحة الكروكي بالموقع
  const MAP_LEGEND = [
    ["2D3748", "المطبخ الساخن"],
    ["3B6998", "التبريد والتجميد والتحلية"],
    ["D4E4F4", "ثلاجات الأجبان والخضار"],
    ["B86B35", "المستودعات الفرعية والجاف"],
    ["DCE3EC", "المستودع المركزي والصالة"],
    ["9B3B3B", "غرف التحكم والسلامة"],
    ["B84A58", "تقطيع اللحوم"],
    ["F2DF99", "المخبوزات والتقطيع"]
  ];
  const CROQUIS_ASPECT = 16 / 8.7; // نفس نسبة الكروكي في الموقع

  const NS = 'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" ' +
    'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" ' +
    'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"';
  const REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/";
  const XML_HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';

  // --------------------------------------------------------------------------
  // 2. أدوات عامة
  // --------------------------------------------------------------------------
  const E = function (inch) { return Math.round(inch * 914400); };

  function xmlEscape(str) {
    if (str === null || str === undefined) return "";
    return String(str)
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&apos;");
  }

  function hex(value, fallback) {
    const h = String(value || "").replace("#", "").trim().toUpperCase();
    if (/^[0-9A-F]{6}$/.test(h)) return h;
    if (/^[0-9A-F]{3}$/.test(h)) return h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    return fallback || "FFFFFF";
  }

  function str(v, fallback) {
    const s = (v === null || v === undefined) ? "" : String(v).replace(/\s+/g, " ").trim();
    return s || (fallback === undefined ? "—" : fallback);
  }

  function isGenerated(url) {
    return typeof url === "string" && url.indexOf("data:image/svg") === 0;
  }

  // تقدير عرض النص بالنقاط (Segoe UI): الحروف العربية أضيق من اللاتينية والأرقام
  function textWidthPt(s, pt, bold) {
    let em = 0;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charCodeAt(i);
      if (ch === 32) em += 0.27;
      else if (ch >= 0x0600 && ch <= 0x06FF) em += 0.45;
      else if (ch >= 48 && ch <= 57) em += 0.56;
      else if (ch === 0x2014 || ch === 0x2022) em += 0.8;
      else em += 0.55;
    }
    return em * pt * (bold ? 1.08 : 1);
  }

  // تقدير محافظ لسعة صندوق نصي ثم القص بعلامة … بدل الفيضان
  function fitText(text, wIn, hIn, pt, bold) {
    const s = str(text, "");
    if (!s) return "";
    const maxW = wIn * 72 * 0.94;
    const maxLines = Math.max(1, Math.floor(((hIn * 72) + (pt * 0.25)) / (pt * 1.15)));
    const words = s.split(" ");
    const lines = [];
    let cur = "";
    for (let i = 0; i < words.length; i++) {
      let w = words[i];
      while (textWidthPt(w, pt, bold) > maxW && w.length > 1) { // كلمة أطول من السطر
        if (cur) { lines.push(cur); cur = ""; }
        let k = w.length;
        while (k > 1 && textWidthPt(w.slice(0, k), pt, bold) > maxW) k--;
        lines.push(w.slice(0, k));
        w = w.slice(k);
      }
      const cand = cur ? cur + " " + w : w;
      if (textWidthPt(cand, pt, bold) <= maxW) cur = cand;
      else { lines.push(cur); cur = w; }
    }
    if (cur) lines.push(cur);
    if (lines.length <= maxLines) return s;
    const kept = lines.slice(0, maxLines);
    let last = kept[maxLines - 1];
    while (last.length > 1 && textWidthPt(last + "…", pt, bold) > maxW) last = last.slice(0, -1);
    last = last.replace(/[\s،,.:؛\-—|•]+$/, "");
    kept[maxLines - 1] = last + "…";
    return kept.join(" ");
  }

  // منطق حالة الصيانة — مطابق لدالة maintenanceInfo في js/app.js
  function dayWord(n) {
    if (n === 1) return "يوم واحد";
    if (n === 2) return "يومين";
    if (n >= 3 && n <= 10) return n + " أيام";
    return n + " يوماً";
  }
  function monthWord(n) {
    if (n === 1) return "شهر واحد";
    if (n === 2) return "شهرين";
    if (n >= 3 && n <= 10) return n + " أشهر";
    return n + " شهراً";
  }
  function maintenanceInfo(dateStr) {
    const none = { cls: "is-none", text: "لم يُحدَّد موعد الصيانة القادمة" };
    if (!dateStr) return none;
    const d = new Date(dateStr + "T00:00:00");
    if (isNaN(d.getTime())) return none;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const days = Math.round((d.getTime() - today.getTime()) / 86400000);
    if (days < 0) return { cls: "is-late", text: "الصيانة متأخرة منذ " + dayWord(-days) };
    if (days === 0) return { cls: "is-soon", text: "الصيانة مستحقة اليوم" };
    if (days <= 30) return { cls: "is-soon", text: "الصيانة القادمة بعد " + dayWord(days) };
    if (days >= 60) return { cls: "is-ok", text: "الصيانة القادمة بعد " + monthWord(Math.round(days / 30)) };
    return { cls: "is-ok", text: "الصيانة القادمة بعد " + dayWord(days) };
  }
  const MAINT_STYLE = {
    "is-ok": { label: "ممتاز", fg: C.ok, bg: C.okBg, ln: C.okLine },
    "is-soon": { label: "قريبة", fg: C.warn, bg: C.warnBg, ln: C.warnLine },
    "is-late": { label: "متأخرة", fg: C.bad, bg: C.badBg, ln: C.badLine },
    "is-none": { label: "غير محدد", fg: C.ink3, bg: C.surface2, ln: C.line2 }
  };

  // --------------------------------------------------------------------------
  // 3. معالجة الصور: أي مصدر ← JPEG + الأبعاد الطبيعية
  // --------------------------------------------------------------------------
  function bytesFromDataUrl(dataUrl) {
    const i = dataUrl.indexOf(",");
    const bin = atob(dataUrl.substring(i + 1));
    const out = new Uint8Array(bin.length);
    for (let k = 0; k < bin.length; k++) out[k] = bin.charCodeAt(k);
    return out;
  }

  function blobToDataUrl(blob) {
    return new Promise(function (resolve, reject) {
      const fr = new FileReader();
      fr.onload = function () { resolve(fr.result); };
      fr.onerror = reject;
      fr.readAsDataURL(blob);
    });
  }

  async function resolveToDataUrl(url) {
    if (!url) return null;
    if (url.indexOf("data:") === 0) return url;
    const embedded = window.EmbeddedProjectMedia && window.EmbeddedProjectMedia[url];
    if (embedded) {
      const mime = embedded.indexOf("iVBOR") === 0 ? "image/png" : "image/jpeg";
      return "data:" + mime + ";base64," + embedded;
    }
    try {
      const resp = await fetch(url);
      if (resp.ok) return await blobToDataUrl(await resp.blob());
    } catch (e) { /* file:// بدون نسخة مضمّنة */ }
    return null;
  }

  // defW/defH: أبعاد افتراضية لرسوم SVG التي لا تعلن أبعادها
  async function loadImage(url, defW, defH) {
    const dataUrl = await resolveToDataUrl(url);
    if (!dataUrl) return null;
    return new Promise(function (resolve) {
      const img = new Image();
      img.onload = function () {
        try {
          const svg = dataUrl.indexOf("data:image/svg") === 0;
          let w = img.naturalWidth || defW || 1200;
          let h = img.naturalHeight || defH || 750;
          if (svg && defW && defH) { w = defW; h = defH; }
          // رسوم SVG تُرسم بدقة مضاعفة للوضوح على البروجكتور، والصور الحقيقية بحد 1600px
          const scale = svg ? Math.min(2, 1600 / Math.max(w, h)) : Math.min(1, 1600 / Math.max(w, h));
          const cw = Math.max(1, Math.round(w * scale));
          const ch = Math.max(1, Math.round(h * scale));
          // JPEG أصلي بحجم مقبول يُستخدم كما هو دون إعادة ضغط
          if (!svg && scale === 1 && dataUrl.indexOf("data:image/jpeg") === 0) {
            resolve({ bytes: bytesFromDataUrl(dataUrl), w: w, h: h });
            return;
          }
          const canvas = document.createElement("canvas");
          canvas.width = cw;
          canvas.height = ch;
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "#FFFFFF";
          ctx.fillRect(0, 0, cw, ch);
          ctx.drawImage(img, 0, 0, cw, ch);
          resolve({ bytes: bytesFromDataUrl(canvas.toDataURL("image/jpeg", 0.88)), w: cw, h: ch });
        } catch (err) {
          resolve(null);
        }
      };
      img.onerror = function () { resolve(null); };
      img.src = dataUrl;
    });
  }

  // --------------------------------------------------------------------------
  // 4. مولّدات XML للأشكال
  // --------------------------------------------------------------------------
  function runXml(r, defaults) {
    const sz = Math.max(SZ.label, r.sz || defaults.sz) * 100;
    const b = (r.b !== undefined ? r.b : defaults.b) ? ' b="1"' : "";
    const color = hex(r.color || defaults.color, C.ink);
    const link = r.link ? '<a:hlinkClick r:id="' + r.link + '" action="ppaction://hlinksldjump"/>' : "";
    return '<a:r><a:rPr lang="ar-SA" altLang="en-US" sz="' + sz + '"' + b + ' dirty="0">' +
      '<a:solidFill><a:srgbClr val="' + color + '"/></a:solidFill>' +
      '<a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/>' + link +
      '</a:rPr><a:t>' + xmlEscape(r.t) + "</a:t></a:r>";
  }

  function paraXml(p, defaults) {
    const algn = p.algn || defaults.algn || "r";
    const rtl = p.rtl === false ? "0" : "1";
    const spcAft = p.spcAft ? '<a:spcAft><a:spcPts val="' + Math.round(p.spcAft * 100) + '"/></a:spcAft>' : "";
    const runs = (p.runs || []).filter(function (r) { return r && r.t !== ""; });
    const endSz = Math.max(SZ.label, p.sz || defaults.sz) * 100;
    return '<a:p><a:pPr algn="' + algn + '" rtl="' + rtl + '"><a:lnSpc><a:spcPct val="100000"/></a:lnSpc>' + spcAft + "</a:pPr>" +
      runs.map(function (r) { return runXml(r, { sz: p.sz || defaults.sz, b: p.b !== undefined ? p.b : defaults.b, color: p.color || defaults.color }); }).join("") +
      '<a:endParaRPr lang="ar-SA" sz="' + endSz + '" dirty="0"><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:endParaRPr></a:p>';
  }

  function geomXml(o) {
    if (o.geom === "roundRect") {
      return '<a:prstGeom prst="roundRect"><a:avLst><a:gd name="adj" fmla="val ' + (o.radius || 7000) + '"/></a:avLst></a:prstGeom>';
    }
    return '<a:prstGeom prst="' + (o.geom || "rect") + '"><a:avLst/></a:prstGeom>';
  }

  function fillXml(color) {
    return color ? '<a:solidFill><a:srgbClr val="' + hex(color) + '"/></a:solidFill>' : "<a:noFill/>";
  }

  function lineXml(color, wPt) {
    return color
      ? '<a:ln w="' + Math.round((wPt || 0.75) * 12700) + '"><a:solidFill><a:srgbClr val="' + hex(color) + '"/></a:solidFill></a:ln>'
      : "<a:ln><a:noFill/></a:ln>";
  }

  // --------------------------------------------------------------------------
  // 5. باني الشريحة
  // --------------------------------------------------------------------------
  function SlideBuilder(index) {
    this.index = index;   // رقم الشريحة (1..N)
    this.xml = [];
    this.rels = [{ id: "rId1", type: "slideLayout", target: "../slideLayouts/slideLayout1.xml" }];
    this.nextShapeId = 2;
    this.notes = null;
    this.bg = C.bg;
  }

  SlideBuilder.prototype.rel = function (type, target) {
    for (let i = 0; i < this.rels.length; i++) {
      if (this.rels[i].type === type && this.rels[i].target === target) return this.rels[i].id;
    }
    const id = "rId" + (this.rels.length + 1);
    this.rels.push({ id: id, type: type, target: target });
    return id;
  };

  SlideBuilder.prototype.slideLink = function (slideNum) {
    if (!slideNum || slideNum === this.index) return null;
    return this.rel("slide", "slide" + slideNum + ".xml");
  };

  // مستطيل / صندوق نصي. الإحداثيات بالبوصة.
  // o: { x,y,w,h, fill, line, lineW, geom, radius, inset, anchor, paras | text+sz+b+color, fit, link, name }
  SlideBuilder.prototype.box = function (o) {
    const id = this.nextShapeId++;
    const inset = o.inset !== undefined ? o.inset : 0.08;
    const insetY = o.insetY !== undefined ? o.insetY : Math.min(inset, 0.06);
    let paras = o.paras;
    if (!paras && o.text !== undefined) {
      const t = o.fit === false ? str(o.text, "") : fitText(o.text, o.w - 2 * inset, o.h - 2 * insetY, o.sz || SZ.body, !!o.b);
      paras = [{ runs: [{ t: t, link: o.runLink }], algn: o.algn, rtl: o.rtl }];
    }
    const defaults = { sz: o.sz || SZ.body, b: !!o.b, color: o.color || C.ink, algn: o.algn || "r" };
    const linkXml = o.link ? '<a:hlinkClick r:id="' + o.link + '" action="ppaction://hlinksldjump"/>' : "";
    const descr = o.descr ? ' descr="' + xmlEscape(o.descr) + '"' : "";
    const txBody = paras
      ? '<p:txBody><a:bodyPr wrap="square" lIns="' + E(inset) + '" tIns="' + E(insetY) + '" rIns="' + E(inset) + '" bIns="' + E(insetY) +
        '" anchor="' + (o.anchor || "t") + '" rtlCol="0"><a:noAutofit/></a:bodyPr><a:lstStyle/>' +
        paras.map(function (p) { return paraXml(p, defaults); }).join("") + "</p:txBody>"
      : "";
    this.xml.push(
      '<p:sp><p:nvSpPr><p:cNvPr id="' + id + '" name="' + xmlEscape(o.name || ("Shape " + id)) + '"' + descr + ">" + linkXml + "</p:cNvPr>" +
      "<p:cNvSpPr" + (paras ? ' txBox="' + (o.fill || o.line ? 0 : 1) + '"' : "") + "/><p:nvPr/></p:nvSpPr>" +
      '<p:spPr><a:xfrm><a:off x="' + E(o.x) + '" y="' + E(o.y) + '"/><a:ext cx="' + Math.max(1, E(o.w)) + '" cy="' + Math.max(1, E(o.h)) + '"/></a:xfrm>' +
      geomXml(o) + fillXml(o.fill) + lineXml(o.line, o.lineW) + "</p:spPr>" +
      txBody + "</p:sp>"
    );
    return id;
  };

  // صورة مع ملاءمة (cover = قص لملء الإطار، contain = احتواء داخل الإطار)
  SlideBuilder.prototype.picture = function (media, o) {
    if (!media) {
      this.box({ x: o.x, y: o.y, w: o.w, h: o.h, fill: C.navy50, line: C.line2, anchor: "ctr", algn: "ctr",
        text: "الصورة غير متاحة", sz: SZ.body, color: C.ink3, name: "ImagePlaceholder" });
      return;
    }
    const id = this.nextShapeId++;
    const rId = this.rel("image", "../media/" + media.name);
    let x = o.x, y = o.y, w = o.w, h = o.h;
    let src = "";
    const boxAR = o.w / o.h;
    const imgAR = media.w / media.h;
    if ((o.fit || "cover") === "cover") {
      if (imgAR > boxAR) {
        const crop = (1 - boxAR / imgAR) / 2;
        src = '<a:srcRect l="' + Math.round(crop * 100000) + '" r="' + Math.round(crop * 100000) + '"/>';
      } else if (imgAR < boxAR) {
        const crop = (1 - imgAR / boxAR) / 2;
        src = '<a:srcRect t="' + Math.round(crop * 100000) + '" b="' + Math.round(crop * 100000) + '"/>';
      }
    } else {
      if (imgAR > boxAR) { h = o.w / imgAR; y = o.y + (o.h - h) / 2; }
      else { w = o.h * imgAR; x = o.x + (o.w - w) / 2; }
    }
    const linkXml = o.link ? '<a:hlinkClick r:id="' + o.link + '" action="ppaction://hlinksldjump"/>' : "";
    this.xml.push(
      '<p:pic><p:nvPicPr><p:cNvPr id="' + id + '" name="' + xmlEscape(o.name || ("Picture " + id)) + '" descr="' + xmlEscape(o.descr || "") + '">' + linkXml + "</p:cNvPr>" +
      '<p:cNvPicPr><a:picLocks noChangeAspect="1"/></p:cNvPicPr><p:nvPr/></p:nvPicPr>' +
      '<p:blipFill><a:blip r:embed="' + rId + '"/>' + src + "<a:stretch><a:fillRect/></a:stretch></p:blipFill>" +
      '<p:spPr><a:xfrm><a:off x="' + E(x) + '" y="' + E(y) + '"/><a:ext cx="' + E(w) + '" cy="' + E(h) + '"/></a:xfrm>' +
      '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>' + lineXml(o.line, o.lineW) + "</p:spPr></p:pic>"
    );
    if (o.generated) {
      // الإبقاء على شارة «رسم توضيحي» كما في الموقع
      this.box({ x: x + w - 1.42, y: y + 0.1, w: 1.32, h: 0.34, fill: C.surface, line: C.line2, geom: "roundRect", radius: 30000,
        anchor: "ctr", algn: "ctr", text: "رسم توضيحي", sz: SZ.label, b: true, color: C.navy700, inset: 0.04, name: "IllustrationBadge" });
    }
  };

  SlideBuilder.prototype.toXml = function () {
    return XML_HEAD + "<p:sld " + NS + ">" +
      '<p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="' + this.bg + '"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree>' +
      '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>' +
      '<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>' +
      this.xml.join("") + "</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>";
  };

  SlideBuilder.prototype.relsXml = function () {
    return XML_HEAD + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
      this.rels.map(function (r) {
        return '<Relationship Id="' + r.id + '" Type="' + REL + r.type + '" Target="' + xmlEscape(r.target) + '"/>';
      }).join("") + "</Relationships>";
  };

  // --------------------------------------------------------------------------
  // 6. عناصر مشتركة: الشريط العلوي الموحد + العنوان + التذييل ورقم الشريحة
  // --------------------------------------------------------------------------
  function chrome(s, ctx, section, title, opts) {
    opts = opts || {};
    s.box({ x: 0, y: 0, w: SLD_W_IN, h: 0.5, fill: C.navy900, name: "TopBar" });
    s.box({ x: 0, y: 0.5, w: SLD_W_IN, h: 0.04, fill: C.gold500, name: "TopBarAccent" });
    s.box({ x: SLD_W_IN / 2, y: 0.04, w: SLD_W_IN / 2 - M, h: 0.42, anchor: "ctr", inset: 0,
      text: ctx.brand, sz: SZ.label, b: true, color: C.surface, name: "TopBarBrand" });
    s.box({ x: M, y: 0.04, w: SLD_W_IN / 2 - M - 0.2, h: 0.42, anchor: "ctr", inset: 0,
      text: section, sz: SZ.label, color: C.gold300, name: "TopBarSection" });
    if (title) {
      const titleW = opts.titleW || CONTENT_W;
      s.box({ x: SLD_W_IN - M - titleW, y: 0.66, w: titleW, h: 0.66, anchor: "ctr", inset: 0,
        text: title, sz: opts.titleSz || SZ.title, b: true, color: C.navy700, name: "Title" });
    }
    // التذييل
    s.box({ x: M, y: 7.02, w: CONTENT_W, h: 0.012, fill: C.line2, name: "FooterRule" });
    s.box({ x: M, y: 7.06, w: 1.6, h: 0.34, anchor: "ctr", inset: 0, algn: "l", rtl: false,
      text: s.index + " / " + ctx.total, sz: SZ.label, color: C.ink3, name: "SlideNumber" });
    s.box({ x: M + 1.8, y: 7.06, w: CONTENT_W - 1.8, h: 0.34, anchor: "ctr", inset: 0,
      text: opts.footer || ctx.footer, sz: SZ.label, color: C.ink3, name: "FooterText" });
  }

  function kpiTile(s, x, y, w, h, value, label, opts) {
    opts = opts || {};
    s.box({ x: x, y: y, w: w, h: h, fill: C.surface, line: C.line, geom: "roundRect", radius: 9000, name: "KpiCard" });
    s.box({ x: x + w - 0.07, y: y + 0.14, w: 0.05, h: h - 0.28, fill: opts.accent || C.gold500, name: "KpiAccent" });
    s.box({ x: x + 0.08, y: y + 0.06, w: w - 0.22, h: 0.28, inset: 0.02, anchor: "t",
      text: label, sz: SZ.label, color: C.ink3, name: "KpiLabel" });
    s.box({ x: x + 0.08, y: y + 0.32, w: w - 0.22, h: h - 0.36, inset: 0.02, anchor: "t",
      text: value, sz: opts.valueSz || SZ.body, b: true, color: opts.valueColor || C.navy800, name: "KpiValue" });
  }

  // --------------------------------------------------------------------------
  // 7. الشرائح
  // --------------------------------------------------------------------------
  function slideCover(s, ctx) {
    const info = ctx.info;
    chrome(s, ctx, "العرض الاستثماري والتشغيلي", null, { footer: str(ctx.exterior[0] && ctx.exterior[0].caption, ctx.footer) });
    // الشريط التعريفي: فوق صورة الواجهة ولا يغطيها
    s.box({ x: M, y: 0.68, w: CONTENT_W, h: 0.66, inset: 0, anchor: "ctr",
      text: str(info.title, "مشروع مطبخ العزيزية المركزي - مبنى 52"), sz: SZ.cover, b: true, color: C.navy700, name: "CoverTitle" });
    s.box({ x: M, y: 1.34, w: CONTENT_W, h: 0.4, inset: 0, anchor: "t",
      text: str(info.subtitle, ""), sz: SZ.body + 2, color: C.ink2, name: "CoverSubtitle" });
    const kpis = [
      [String(ctx.rooms.length), "قسماً تشغيلياً"],
      [String(ctx.totalAssets), "أصلاً ومعدة صناعية"],
      [String(ctx.totalStaff), "كادراً بشرياً متخصصاً"],
      [ctx.capacity.value, "وجبة يومياً (طاقة تشغيلية)"]
    ];
    const gap = 0.18, tw = (CONTENT_W - gap * 3) / 4, th = 0.98, ty = 1.84;
    kpis.forEach(function (k, i) {
      const x = SLD_W_IN - M - tw - i * (tw + gap);
      s.box({ x: x, y: ty, w: tw, h: th, fill: C.surface, line: C.line, geom: "roundRect", radius: 9000, name: "CoverKpi" });
      s.box({ x: x + tw - 0.07, y: ty + 0.16, w: 0.05, h: th - 0.32, fill: C.gold500, name: "CoverKpiAccent" });
      s.box({ x: x + 0.12, y: ty + 0.04, w: tw - 0.32, h: 0.56, inset: 0.02, anchor: "ctr",
        text: k[0], sz: SZ.kpi, b: true, color: C.gold700, name: "CoverKpiValue" });
      s.box({ x: x + 0.12, y: ty + 0.58, w: tw - 0.32, h: 0.34, inset: 0.02, anchor: "t",
        text: k[1], sz: SZ.label, color: C.ink2, name: "CoverKpiLabel" });
    });
    const imgY = ty + th + 0.18;
    s.picture(ctx.media.exterior[0], { x: M, y: imgY, w: CONTENT_W, h: 6.92 - imgY, fit: "cover", line: C.line2,
      descr: str(ctx.exterior[0] && ctx.exterior[0].caption, "صورة الواجهة الخارجية للمطبخ المركزي"), name: "ExteriorPhoto",
      generated: ctx.exterior[0] && isGenerated(ctx.exterior[0].url) });
  }

  function slideExteriorGallery(s, ctx, imgIdx) {
    const item = ctx.exterior[imgIdx];
    chrome(s, ctx, "واجهة المطبخ المركزي", "واجهة المطبخ — صورة " + (imgIdx + 1) + " من " + ctx.exterior.length);
    s.picture(ctx.media.exterior[imgIdx], { x: M, y: 1.45, w: CONTENT_W, h: 4.95, fit: "contain",
      descr: str(item.caption, "صورة الواجهة"), name: "ExteriorPhoto", generated: isGenerated(item.url) });
    s.box({ x: M, y: 6.48, w: CONTENT_W, h: 0.46, anchor: "ctr", text: str(item.caption, ""), sz: SZ.body, color: C.ink2, name: "Caption" });
  }

  function slideOverview(s, ctx) {
    chrome(s, ctx, "فهرس الأقسام", "نظرة عامة على أقسام المطبخ");
    s.box({ x: M, y: 1.3, w: CONTENT_W, h: 0.4, inset: 0, anchor: "ctr",
      text: ctx.rooms.length + " قسماً موزعة على " + ctx.categories.length + " فئات تشغيلية — المساحة الإجمالية " + str(ctx.info.totalArea) +
        " — الطاقة " + str(ctx.info.dailyCapacity), sz: SZ.body, color: C.ink2, name: "OverviewSummary" });
    const cats = ctx.categories;
    const cols = 3, rows = Math.max(1, Math.ceil(cats.length / cols));
    const gap = 0.2, top = 1.85, bottom = 6.9;
    const cw = (CONTENT_W - gap * (cols - 1)) / cols;
    const ch = (bottom - top - gap * (rows - 1)) / rows;
    cats.forEach(function (cat, i) {
      const col = i % cols, row = Math.floor(i / cols);
      const x = SLD_W_IN - M - cw - col * (cw + gap);
      const y = top + row * (ch + gap);
      const color = CATEGORY_COLORS[cat.name] || C.navy600;
      s.box({ x: x, y: y, w: cw, h: ch, fill: C.surface, line: C.line, geom: "roundRect", radius: 6000, name: "CategoryCard" });
      s.box({ x: x + cw - 0.09, y: y + 0.12, w: 0.06, h: ch - 0.24, fill: color, name: "CategoryAccent" });
      s.box({ x: x + 0.75, y: y + 0.12, w: cw - 0.95, h: 0.42, inset: 0.02, anchor: "ctr",
        text: cat.name, sz: SZ.h2, b: true, color: C.navy800, name: "CategoryName" });
      s.box({ x: x + 0.12, y: y + 0.1, w: 0.62, h: 0.46, inset: 0.02, anchor: "ctr", algn: "l", rtl: false,
        text: String(cat.rooms.length), sz: SZ.kpi, b: true, color: color, name: "CategoryCount" });
      // أسماء الأقسام كروابط داخلية إلى شرائحها (قائمة فقرات مستقلة بعرض كامل لمنع أي تداخل)
      const listW = cw - 0.24, listH = ch - 0.60;
      const count = cat.rooms.length;
      const maxItems = 7;
      const shownCount = count <= maxItems ? count : (maxItems - 1);
      const paras = [];
      for (let k = 0; k < shownCount; k++) {
        const r = cat.rooms[k];
        paras.push({
          runs: [{ t: "•  " + str(r.room.name), link: s.slideLink(ctx.roomSlide[r.room.id]), color: C.navy700 }],
          sz: SZ.label,
          spcAft: 2
        });
      }
      if (count > shownCount) {
        paras.push({
          runs: [{ t: "•  … و" + (count - shownCount) + " أقسام أخرى (مفصلة بالكروكي)", link: s.slideLink(ctx.croquisSlide), color: C.gold700 }],
          sz: SZ.label,
          spcAft: 2
        });
      }
      s.box({ x: x + 0.12, y: y + 0.58, w: listW, h: listH, inset: 0.02, anchor: "t",
        paras: paras, name: "CategoryRooms" });
    });
  }

  function slideCroquis(s, ctx) {
    chrome(s, ctx, "الخريطة الكروكية", "الخريطة الكروكية للأقسام", { titleW: 8.6 });
    s.box({ x: M, y: 0.72, w: 4.1, h: 0.56, inset: 0, anchor: "ctr",
      text: "اضغط على أي قسم للانتقال إلى شريحته", sz: SZ.label, color: C.ink3, name: "CroquisHint" });
    const legendW = 2.75, gapL = 0.2;
    const availW = CONTENT_W - legendW - gapL, availH = 6.9 - 1.42;
    let mw = availW, mh = mw / CROQUIS_ASPECT;
    if (mh > availH) { mh = availH; mw = mh * CROQUIS_ASPECT; }
    const mx = SLD_W_IN - M - mw, my = 1.42 + (availH - mh) / 2;
    s.box({ x: mx, y: my, w: mw, h: mh, fill: "F7F9FC", line: C.line2, name: "CroquisFrame" });
    ctx.zones.forEach(function (z) {
      s.box({ x: mx + mw * (+z.x || 0) / 100, y: my + mh * (+z.y || 0) / 100, w: mw * (+z.w || 0) / 100, h: mh * (+z.h || 0) / 100,
        fill: hex(z.bg, "E2E8F0"), name: "Zone " + str(z.id, "") });
    });
    const numbered = [];
    ctx.rooms.forEach(function (room, idx) {
      const rx = mx + mw * (+room.x || 0) / 100, ry = my + mh * (+room.y || 0) / 100;
      const rw = mw * (+room.w || 0) / 100, rh = mh * (+room.h || 0) / 100;
      if (rw <= 0 || rh <= 0) return;
      const label = str(room.mapLabel || room.name);
      // هل يتسع الاسم بخط 12pt؟ وإلا يُستبدل برقم مع مفتاح جانبي
      const cpl = Math.floor(((rw - 0.06) * 72) / (SZ.label * 0.56));
      const lines = Math.floor(((rh - 0.04) * 72) / (SZ.label * 1.25));
      const longest = label.split(" ").reduce(function (m, w) { return Math.max(m, w.length); }, 0);
      let text = label;
      if (lines < 1 || longest > cpl || fitText(label, rw - 0.06, rh - 0.04, SZ.label, false) !== label) {
        text = String(idx + 1);
        numbered.push({ n: idx + 1, room: room });
        if ((rw * 72) < SZ.label * 0.6 * text.length || (rh * 72) < SZ.label * 1.1) text = "";
      }
      s.box({ x: rx, y: ry, w: rw, h: rh, fill: hex(room.color, "3B6998"), line: C.surface, lineW: 1,
        inset: 0.03, insetY: 0.02, anchor: "ctr", algn: "ctr", text: text, fit: false, sz: SZ.label, b: true,
        color: hex(room.textColor, "FFFFFF"), link: s.slideLink(ctx.roomSlide[room.id]),
        name: "Room " + str(room.id, ""), descr: label });
    });
    // وسيلة الإيضاح (يسار الخريطة)
    const lx = M, ly = 1.42;
    s.box({ x: lx, y: ly, w: legendW, h: availH, fill: C.surface, line: C.line, geom: "roundRect", radius: 4000, name: "LegendCard" });
    s.box({ x: lx + 0.1, y: ly + 0.08, w: legendW - 0.2, h: 0.34, inset: 0.02, anchor: "ctr",
      text: "وسيلة الإيضاح", sz: SZ.body, b: true, color: C.navy800, name: "LegendTitle" });
    let yy = ly + 0.48;
    MAP_LEGEND.forEach(function (it) {
      s.box({ x: lx + legendW - 0.38, y: yy + 0.06, w: 0.24, h: 0.2, fill: it[0], line: C.line2, name: "LegendSwatch" });
      s.box({ x: lx + 0.1, y: yy, w: legendW - 0.55, h: 0.32, inset: 0.02, anchor: "ctr",
        text: it[1], sz: SZ.label, color: C.ink2, name: "LegendLabel" });
      yy += 0.33;
    });
    if (numbered.length) {
      yy += 0.08;
      s.box({ x: lx + 0.1, y: yy, w: legendW - 0.2, h: 0.012, fill: C.line2, name: "LegendRule" });
      yy += 0.06;
      const rowH = 0.27;
      const room = Math.floor((ly + availH - 0.06 - yy) / rowH);
      const twoCols = numbered.length > room;
      const perCol = twoCols ? room : numbered.length;
      const colW = twoCols ? (legendW - 0.2) / 2 : legendW - 0.2;
      numbered.slice(0, twoCols ? room * 2 : room).forEach(function (it, i) {
        const c = Math.floor(i / perCol), r = i % perCol;
        const x = lx + legendW - 0.1 - colW - c * colW;
        s.box({ x: x, y: yy + r * rowH, w: colW, h: rowH, inset: 0.02, anchor: "ctr",
          paras: [{ runs: [
            { t: it.n + " ", b: true, color: C.navy800 },
            { t: fitText(str(it.room.mapLabel || it.room.name), colW - 0.35, rowH, SZ.label, false), color: C.ink2, link: s.slideLink(ctx.roomSlide[it.room.id]) }
          ] }], sz: SZ.label, name: "RoomKey" });
      });
    }
  }

  function slideEvacuation(s, ctx) {
    chrome(s, ctx, "المخطط الهندسي", "المخطط الهندسي المعتمد — مخطط الإخلاء B52");
    s.picture(ctx.media.evacuation, { x: M, y: 1.45, w: CONTENT_W, h: 5.0, fit: "contain", line: C.line2,
      descr: "المخطط الهندسي ومخطط الإخلاء المعتمد للمبنى 52 مع اتجاهات المخارج", name: "EvacuationPlan" });
    s.box({ x: M, y: 6.5, w: CONTENT_W, h: 0.44, anchor: "ctr",
      text: "يوضح المخطط أرقام الغرف المعتمدة واتجاهات مخارج الطوارئ ومسارات الإخلاء.", sz: SZ.body, color: C.ink2, name: "Caption" });
  }

  function roomSection(ctx, room, idx) {
    return "القسم " + (idx + 1) + " من " + ctx.rooms.length + "  |  " + str(room.category);
  }

  function slideRoom(s, ctx, room, idx) {
    chrome(s, ctx, roomSection(ctx, room, idx), str(room.name), { titleW: CONTENT_W - 3.3 });
    // شارة الفئة بجوار العنوان + رابط العودة للكروكي كنص (ليس زراً)
    const catColor = CATEGORY_COLORS[room.category] || C.navy600;
    s.box({ x: M, y: 0.78, w: 3.1, h: 0.42, fill: C.gold100, line: C.gold300, geom: "roundRect", radius: 30000,
      anchor: "ctr", algn: "ctr", text: str(room.category), sz: SZ.label, b: true, color: C.gold700, inset: 0.06, name: "CategoryChip" });

    const imgX = M, imgY = 1.45, imgW = 7.35, imgH = imgW / 1.6;
    const imgs = Array.isArray(room.images) ? room.images : [];
    const first = imgs[0] || { url: room.image, caption: room.name };
    s.picture(ctx.media.room[room.id], { x: imgX, y: imgY, w: imgW, h: imgH, fit: "cover", line: C.line2,
      descr: str(first.caption, "صورة " + str(room.name)), name: "RoomPhoto", generated: isGenerated(first.url) });
    s.box({ x: imgX, y: imgY + imgH + 0.06, w: imgW, h: 0.36, inset: 0.02, anchor: "t",
      text: str(first.caption, "") + (imgs.length > 1 ? "  (" + imgs.length + " صور متاحة في الموقع)" : ""), sz: SZ.label, color: C.ink3, name: "PhotoCaption" });

    const colX = imgX + imgW + 0.25, colW = SLD_W_IN - M - colX;
    const tw = (colW - 0.14) / 2, th = 0.94, gy = 0.08;
    const assetsN = (room.assets || []).length, staffN = (room.staff || []).length;
    const tiles = [
      ["المساحة", str(room.area)],
      ["درجة الحرارة", str(room.temp)],
      ["الحالة التشغيلية", str(room.status)],
      ["الرمز في المخطط", str(room.b52Code)],
      ["الأصول والمعدات", assetsN + (assetsN === 1 ? " أصل" : " أصول")],
      ["الكوادر البشرية", staffN + (staffN === 1 ? " موظف" : " موظفين")]
    ];
    tiles.forEach(function (t, i) {
      const c = i % 2, r = Math.floor(i / 2);
      kpiTile(s, SLD_W_IN - M - tw - c * (tw + 0.14), imgY + r * (th + gy), tw, th, t[1], t[0],
        { accent: i >= 4 ? C.navy600 : C.gold500 });
    });
    const dy = imgY + 3 * (th + gy) + 0.04, dh = 6.92 - dy;
    s.box({ x: colX, y: dy, w: colW, h: dh, fill: C.surface, line: C.line, geom: "roundRect", radius: 6000, name: "DescCard" });
    s.box({ x: colX + 0.12, y: dy + 0.06, w: colW - 0.24, h: 0.32, inset: 0.02, anchor: "ctr",
      text: "نبذة عن القسم", sz: SZ.label, b: true, color: catColor, name: "DescLabel" });
    s.box({ x: colX + 0.12, y: dy + 0.38, w: colW - 0.24, h: dh - 0.46, inset: 0.02, anchor: "t",
      text: str(room.description, "لا يوجد وصف مسجّل لهذا القسم."), sz: SZ.body, color: C.ink, name: "Description" });

    s.notes = [
      str(room.name) + " — " + str(room.category),
      str(room.description, ""),
      "المساحة: " + str(room.area) + " | الحرارة: " + str(room.temp) + " | الحالة: " + str(room.status),
      "الأصول: " + assetsN + " | الكوادر: " + staffN
    ];
  }

  function slideAssets(s, ctx, room, idx, list, page, pages) {
    chrome(s, ctx, roomSection(ctx, room, idx),
      "أصول ومعدات — " + str(room.name) + (pages > 1 ? " (" + page + "/" + pages + ")" : ""));
    const gap = 0.18, top = 1.45, bottom = 6.92;
    const cw = (CONTENT_W - gap) / 2, ch = (bottom - top - gap) / 2;
    list.forEach(function (it, i) {
      const ast = it.asset;
      const col = i % 2, row = Math.floor(i / 2);
      const x = SLD_W_IN - M - cw - col * (cw + gap), y = top + row * (ch + gap);
      s.box({ x: x, y: y, w: cw, h: ch, fill: C.surface, line: C.line, geom: "roundRect", radius: 5000, name: "AssetCard" });
      // الصورة يسار البطاقة
      const iw = 2.2, ih = iw / (600 / 380);
      s.picture(ctx.media.asset[it.key], { x: x + 0.14, y: y + 0.14, w: iw, h: ih, fit: "cover", line: C.line,
        descr: "صورة الأصل: " + str(ast.name), name: "AssetPhoto", generated: isGenerated(ast.image) });
      const m = maintenanceInfo(ast.nextMaintDate);
      const ms = MAINT_STYLE[m.cls];
      s.box({ x: x + 0.14, y: y + 0.24 + ih, w: iw, h: 0.62, fill: ms.bg, line: ms.ln, geom: "roundRect", radius: 16000,
        inset: 0.06, insetY: 0.03, anchor: "ctr",
        paras: [{ runs: [{ t: "● الصيانة: " + ms.label, b: true, color: ms.fg }], sz: SZ.label },
                { runs: [{ t: fitText(m.text, iw - 0.12, 0.25, SZ.label, false), color: ms.fg }], sz: SZ.label }],
        name: "MaintenanceBadge" });
      s.box({ x: x + 0.14, y: y + 0.94 + ih, w: iw, h: 0.32, inset: 0.04, anchor: "ctr",
        text: "الحالة: " + str(ast.status), sz: SZ.label, b: true, color: C.navy700, name: "AssetStatus" });
      // النصوص يمين البطاقة
      const tx = x + 0.14 + iw + 0.18, tW = cw - (tx - x) - 0.16;
      let ty = y + 0.12;
      s.box({ x: tx, y: ty, w: tW, h: 0.64, inset: 0.02, anchor: "t", text: str(ast.name), sz: SZ.body + 1, b: true, color: C.navy800, name: "AssetName" });
      ty += 0.66;
      s.box({ x: tx, y: ty, w: tW, h: 0.27, inset: 0.02, anchor: "t",
        text: str(ast.code, "") + (ast.brand ? "  •  " + ast.brand : ""), sz: SZ.label, color: C.ink3, name: "AssetCode" });
      ty += 0.3;
      s.box({ x: tx, y: ty, w: tW, h: 0.27, inset: 0.02, anchor: "t",
        text: "التركيب: " + str(ast.installDate) + "   |   آخر صيانة: " + str(ast.lastMaintDate), sz: SZ.label, color: C.ink2, name: "AssetDates" });
      ty += 0.27;
      s.box({ x: tx, y: ty, w: tW, h: 0.27, inset: 0.02, anchor: "t",
        text: "الصيانة القادمة: " + str(ast.nextMaintDate), sz: SZ.label, b: true, color: ms.fg, name: "AssetNextMaint" });
      ty += 0.32;
      s.box({ x: tx, y: ty, w: tW, h: y + ch - 0.1 - ty, inset: 0.02, anchor: "t",
        text: str(ast["function"], str(ast.specs)), sz: SZ.body, color: C.ink, name: "AssetFunction" });
    });
  }

  function slideStaff(s, ctx, room, idx, list, page, pages) {
    chrome(s, ctx, roomSection(ctx, room, idx),
      "الكوادر البشرية — " + str(room.name) + (pages > 1 ? " (" + page + "/" + pages + ")" : ""));
    const gap = 0.18, top = 1.45, bottom = 6.92;
    const cw = (CONTENT_W - gap * (STAFF_PER_SLIDE - 1)) / STAFF_PER_SLIDE, ch = bottom - top;
    list.forEach(function (it, i) {
      const emp = it.emp;
      const cv = emp.cv || {};
      const x = SLD_W_IN - M - cw - i * (cw + gap), y = top;
      s.box({ x: x, y: y, w: cw, h: ch, fill: C.surface, line: C.line, geom: "roundRect", radius: 4000, name: "StaffCard" });
      s.box({ x: x, y: y, w: cw, h: 0.07, fill: C.navy700, name: "StaffCardAccent" });
      const av = 0.95;
      s.picture(ctx.media.staff[it.key], { x: x + cw - 0.14 - av, y: y + 0.22, w: av, h: av, fit: "cover", line: C.line2,
        descr: "صورة الموظف: " + str(emp.name), name: "StaffAvatar" });
      const hx = x + 0.14, hw = cw - av - 0.36;
      s.box({ x: hx, y: y + 0.18, w: hw, h: 0.66, inset: 0.02, anchor: "t", text: str(emp.name), sz: SZ.h2, b: true, color: C.navy800, name: "StaffName" });
      s.box({ x: hx, y: y + 0.82, w: hw, h: 0.44, inset: 0.02, anchor: "t", text: str(emp.position), sz: SZ.label, b: true, color: C.gold700, name: "StaffPosition" });
      let yy = y + 1.36;
      const rows = [
        ["الرقم الوظيفي", str(emp.empCode)],
        ["تاريخ الانضمام", str(emp.hireDate)],
        ["الوردية", str(emp.shift)]
      ];
      rows.forEach(function (r) {
        s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 0.3, inset: 0.02, anchor: "ctr",
          paras: [{ runs: [{ t: r[0] + ": ", b: true, color: C.ink3 }, { t: fitText(r[1], cw - 1.6, 0.28, SZ.label, false), color: C.ink }] }],
          sz: SZ.label, name: "StaffField" });
        yy += 0.3;
      });
      yy += 0.06;
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 0.012, fill: C.line, name: "StaffRule" });
      yy += 0.08;
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 0.28, inset: 0.02, anchor: "t", text: "المهام", sz: SZ.label, b: true, color: C.navy600, name: "DutiesLabel" });
      yy += 0.28;
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 1.02, inset: 0.02, anchor: "t", text: str(emp.duties), sz: SZ.body, color: C.ink, name: "Duties" });
      yy += 1.08;
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 0.28, inset: 0.02, anchor: "t", text: "السيرة الذاتية", sz: SZ.label, b: true, color: C.navy600, name: "CvLabel" });
      yy += 0.28;
      const cvLine = [cv.education, cv.experienceYears ? "خبرة " + cv.experienceYears : "", cv.previousJobs]
        .filter(function (v) { return v && String(v).trim(); }).join(" — ");
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: 0.78, inset: 0.02, anchor: "t", text: str(cvLine), sz: SZ.body, color: C.ink, name: "CvSummary" });
      yy += 0.82;
      const skills = Array.isArray(cv.skills) ? cv.skills.join("، ") : str(cv.skills, "");
      const certs = str(cv.certifications, "");
      s.box({ x: x + 0.14, y: yy, w: cw - 0.28, h: y + ch - 0.1 - yy, inset: 0.02, anchor: "t",
        text: (certs ? "الشهادات: " + certs : "") + (skills ? (certs ? " | " : "") + "المهارات: " + skills : ""), sz: SZ.label, color: C.ok, name: "CvCerts" });
    });
  }

  function slideClosing(s, ctx) {
    s.bg = C.navy900;
    s.box({ x: 0, y: 0, w: SLD_W_IN, h: 0.04, fill: C.gold500, name: "TopAccent" });
    s.box({ x: M, y: 2.0, w: CONTENT_W, h: 0.9, anchor: "ctr", algn: "ctr", text: "شكراً لحسن استماعكم", sz: 40, b: true, color: C.surface, name: "ClosingTitle" });
    s.box({ x: M, y: 2.95, w: CONTENT_W, h: 0.5, anchor: "ctr", algn: "ctr", text: str(ctx.info.title, ""), sz: SZ.h2, color: C.gold300, name: "ClosingProject" });
    s.box({ x: 4.6, y: 3.65, w: SLD_W_IN - 9.2, h: 0.02, fill: C.gold500, name: "ClosingRule" });
    const lines = [str(ctx.info.clientName, ""),
      "المساحة الإجمالية: " + str(ctx.info.totalArea) + "   |   الطاقة الإنتاجية: " + str(ctx.info.dailyCapacity),
      ctx.rooms.length + " قسماً  •  " + ctx.totalAssets + " أصلاً  •  " + ctx.totalStaff + " كادراً"];
    s.box({ x: M, y: 3.85, w: CONTENT_W, h: 1.4, anchor: "t", algn: "ctr",
      paras: lines.filter(Boolean).map(function (t) { return { runs: [{ t: t }], algn: "ctr", spcAft: 6 }; }),
      sz: SZ.body + 2, color: C.navy200, name: "ClosingInfo" });
    s.box({ x: M, y: 7.06, w: 1.6, h: 0.34, anchor: "ctr", inset: 0, algn: "l", rtl: false,
      text: s.index + " / " + ctx.total, sz: SZ.label, color: C.navy200, name: "SlideNumber" });
  }

  // --------------------------------------------------------------------------
  // 8. أجزاء الحزمة الثابتة
  // --------------------------------------------------------------------------
  const GRP = '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>' +
    '<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>';
  const CLRMAP = '<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/>';

  function themeXml(name) {
    return XML_HEAD + '<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="' + name + '"><a:themeElements>' +
      '<a:clrScheme name="Aziziyah52">' +
      '<a:dk1><a:srgbClr val="' + C.ink + '"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1>' +
      '<a:dk2><a:srgbClr val="' + C.navy900 + '"/></a:dk2><a:lt2><a:srgbClr val="' + C.bg + '"/></a:lt2>' +
      '<a:accent1><a:srgbClr val="' + C.navy700 + '"/></a:accent1><a:accent2><a:srgbClr val="' + C.gold500 + '"/></a:accent2>' +
      '<a:accent3><a:srgbClr val="' + C.navy600 + '"/></a:accent3><a:accent4><a:srgbClr val="' + C.gold700 + '"/></a:accent4>' +
      '<a:accent5><a:srgbClr val="' + C.ok + '"/></a:accent5><a:accent6><a:srgbClr val="' + C.bad + '"/></a:accent6>' +
      '<a:hlink><a:srgbClr val="' + C.navy600 + '"/></a:hlink><a:folHlink><a:srgbClr val="' + C.navy800 + '"/></a:folHlink></a:clrScheme>' +
      '<a:fontScheme name="SafeArabic">' +
      '<a:majorFont><a:latin typeface="' + FONT + '"/><a:ea typeface=""/><a:cs typeface="' + FONT + '"/><a:font script="Arab" typeface="' + FONT + '"/></a:majorFont>' +
      '<a:minorFont><a:latin typeface="' + FONT + '"/><a:ea typeface=""/><a:cs typeface="' + FONT + '"/><a:font script="Arab" typeface="' + FONT + '"/></a:minorFont></a:fontScheme>' +
      '<a:fmtScheme name="Flat"><a:fillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:fillStyleLst>' +
      '<a:lnStyleLst><a:ln w="9525"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln><a:ln w="12700"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln><a:ln w="19050"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln></a:lnStyleLst>' +
      '<a:effectStyleLst><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle></a:effectStyleLst>' +
      '<a:bgFillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme>' +
      "</a:themeElements><a:objectDefaults/><a:extraClrSchemeLst/></a:theme>";
  }

  function notesMasterXml() {
    return XML_HEAD + "<p:notesMaster " + NS + "><p:cSld><p:bg><p:bgRef idx=\"1001\"><a:schemeClr val=\"bg1\"/></p:bgRef></p:bg><p:spTree>" + GRP +
      '<p:sp><p:nvSpPr><p:cNvPr id="2" name="Slide Image Placeholder 1"/><p:cNvSpPr><a:spLocks noGrp="1" noRot="1" noChangeAspect="1"/></p:cNvSpPr><p:nvPr><p:ph type="sldImg" idx="2"/></p:nvPr></p:nvSpPr>' +
      '<p:spPr><a:xfrm><a:off x="381000" y="685800"/><a:ext cx="6096000" cy="3429000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/><a:ln w="12700"><a:solidFill><a:prstClr val="black"/></a:solidFill></a:ln></p:spPr></p:sp>' +
      '<p:sp><p:nvSpPr><p:cNvPr id="3" name="Notes Placeholder 2"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" sz="quarter" idx="3"/></p:nvPr></p:nvSpPr>' +
      '<p:spPr><a:xfrm><a:off x="685800" y="4343400"/><a:ext cx="5486400" cy="4114800"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr>' +
      '<p:txBody><a:bodyPr vert="horz" lIns="91440" tIns="45720" rIns="91440" bIns="45720" rtlCol="0"/><a:lstStyle/><a:p><a:pPr algn="r" rtl="1"/><a:endParaRPr lang="ar-SA"/></a:p></p:txBody></p:sp>' +
      "</p:spTree></p:cSld>" + CLRMAP +
      '<p:notesStyle><a:lvl1pPr marL="0" algn="r" rtl="1"><a:defRPr sz="1400"><a:solidFill><a:schemeClr val="tx1"/></a:solidFill><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:defRPr></a:lvl1pPr></p:notesStyle></p:notesMaster>';
  }

  function notesSlideXml(lines) {
    const paras = lines.filter(function (l) { return l; }).map(function (l) {
      return '<a:p><a:pPr algn="r" rtl="1"/><a:r><a:rPr lang="ar-SA" sz="1400" dirty="0"><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:rPr><a:t>' + xmlEscape(l) + "</a:t></a:r></a:p>";
    }).join("");
    return XML_HEAD + "<p:notes " + NS + "><p:cSld><p:spTree>" + GRP +
      '<p:sp><p:nvSpPr><p:cNvPr id="2" name="Slide Image Placeholder 1"/><p:cNvSpPr><a:spLocks noGrp="1" noRot="1" noChangeAspect="1"/></p:cNvSpPr><p:nvPr><p:ph type="sldImg"/></p:nvPr></p:nvSpPr><p:spPr/></p:sp>' +
      '<p:sp><p:nvSpPr><p:cNvPr id="3" name="Notes Placeholder 2"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="body" idx="1"/></p:nvPr></p:nvSpPr><p:spPr/>' +
      '<p:txBody><a:bodyPr/><a:lstStyle/>' + paras + "</p:txBody></p:sp>" +
      "</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:notes>";
  }

  // --------------------------------------------------------------------------
  // 9. ضغط ZIP (تخزين بدون ضغط — متوافق مع PowerPoint وLibreOffice)
  // --------------------------------------------------------------------------
  const crcTable = (function () {
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      table[n] = c >>> 0;
    }
    return table;
  })();

  function crc32(bytes) {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < bytes.length; i++) crc = (crc >>> 8) ^ crcTable[(crc ^ bytes[i]) & 0xFF];
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  function createZipBlob(files) {
    const enc = new TextEncoder();
    const localParts = [], centralParts = [];
    let offset = 0;
    files.forEach(function (f) {
      const nameBytes = enc.encode(f.name);
      const data = f.data instanceof Uint8Array ? f.data : enc.encode(f.data);
      const crc = crc32(data);
      const lh = new Uint8Array(30 + nameBytes.length);
      const lv = new DataView(lh.buffer);
      lv.setUint32(0, 0x04034b50, true); lv.setUint16(4, 20, true); lv.setUint16(6, 0x0800, true);
      lv.setUint16(8, 0, true); lv.setUint16(10, 0x5400, true); lv.setUint16(12, 0x5B61, true);
      lv.setUint32(14, crc, true); lv.setUint32(18, data.length, true); lv.setUint32(22, data.length, true);
      lv.setUint16(26, nameBytes.length, true); lv.setUint16(28, 0, true);
      lh.set(nameBytes, 30);
      localParts.push(lh, data);
      const chd = new Uint8Array(46 + nameBytes.length);
      const cv = new DataView(chd.buffer);
      cv.setUint32(0, 0x02014b50, true); cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
      cv.setUint16(8, 0x0800, true); cv.setUint16(10, 0, true); cv.setUint16(12, 0x5400, true); cv.setUint16(14, 0x5B61, true);
      cv.setUint32(16, crc, true); cv.setUint32(20, data.length, true); cv.setUint32(24, data.length, true);
      cv.setUint16(28, nameBytes.length, true);
      cv.setUint32(42, offset, true);
      chd.set(nameBytes, 46);
      centralParts.push(chd);
      offset += lh.length + data.length;
    });
    const centralSize = centralParts.reduce(function (a, p) { return a + p.length; }, 0);
    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true);
    ev.setUint16(8, files.length, true); ev.setUint16(10, files.length, true);
    ev.setUint32(12, centralSize, true); ev.setUint32(16, offset, true);
    return new Blob(localParts.concat(centralParts, [eocd]), {
      type: "application/vnd.openxmlformats-officedocument.presentationml.presentation"
    });
  }

  // --------------------------------------------------------------------------
  // 10. التجميع
  // --------------------------------------------------------------------------
  function chunk(arr, n) {
    const out = [];
    for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
    return out;
  }

  function parseCapacity(text) {
    const s = str(text, "");
    const m = /[\d٠-٩][\d٠-٩,.]*/.exec(s);
    if (!m) return { value: s || "—", label: "الطاقة الإنتاجية" };
    const rest = s.replace(m[0], "").trim();
    return { value: m[0], label: (rest || "وجبة يومياً") + " — الطاقة الإنتاجية" };
  }

  async function buildPptx(kitchenData) {
    const data = kitchenData || {};
    const rooms = Array.isArray(data.rooms) ? data.rooms : [];
    const info = data.projectInfo || {};
    const exterior = (Array.isArray(info.exteriorImages) && info.exteriorImages.length)
      ? info.exteriorImages
      : [{ url: info.exteriorImage || "assets/kitchen_exterior.jpg", caption: "الواجهة الخارجية للمطبخ المركزي 52" }];

    // تجميع الفئات (بالترتيب المعتمد ثم أي فئة جديدة)
    const catMap = {};
    rooms.forEach(function (room) {
      const name = str(room.category, "أخرى");
      (catMap[name] = catMap[name] || []).push({ room: room });
    });
    const catNames = CATEGORY_ORDER.filter(function (c) { return catMap[c]; })
      .concat(Object.keys(catMap).filter(function (c) { return CATEGORY_ORDER.indexOf(c) === -1; }));

    // مخطط الشرائح (لحساب أرقام الشرائح والروابط الداخلية مسبقاً)
    const plan = [{ kind: "cover" }];
    for (let i = 1; i < exterior.length; i++) plan.push({ kind: "exterior", idx: i });
    plan.push({ kind: "overview" }, { kind: "croquis" }, { kind: "evacuation" });
    const roomSlide = {};
    rooms.forEach(function (room, idx) {
      plan.push({ kind: "room", room: room, idx: idx });
      roomSlide[room.id] = plan.length;
      const assets = (room.assets || []).map(function (a, k) { return { asset: a, key: room.id + "|a|" + k }; });
      const aPages = chunk(assets, ASSETS_PER_SLIDE);
      aPages.forEach(function (list, p) { plan.push({ kind: "assets", room: room, idx: idx, list: list, page: p + 1, pages: aPages.length }); });
      const staff = (room.staff || []).map(function (e, k) { return { emp: e, key: room.id + "|s|" + k }; });
      const sPages = chunk(staff, STAFF_PER_SLIDE);
      sPages.forEach(function (list, p) { plan.push({ kind: "staff", room: room, idx: idx, list: list, page: p + 1, pages: sPages.length }); });
    });
    plan.push({ kind: "closing" });

    // تجهيز الصور (مع إزالة التكرار)
    const files = [];
    const mediaCache = {};
    let mediaCounter = 0;
    async function media(url, defW, defH) {
      if (!url) return null;
      const key = url + "|" + (defW || 0);
      if (mediaCache[key] !== undefined) return mediaCache[key];
      const img = await loadImage(url, defW, defH);
      if (!img) { mediaCache[key] = null; return null; }
      const name = "image" + (++mediaCounter) + ".jpg";
      files.push({ name: "ppt/media/" + name, data: img.bytes });
      mediaCache[key] = { name: name, w: img.w, h: img.h };
      return mediaCache[key];
    }
    const V = window.KitchenVisuals;
    const ctxMedia = { exterior: [], room: {}, asset: {}, staff: {}, evacuation: null };
    for (let i = 0; i < exterior.length; i++) ctxMedia.exterior.push(await media(exterior[i].url));
    ctxMedia.evacuation = await media(info.evacuationImage || "assets/evacuation_plan_b52.jpg");
    for (let r = 0; r < rooms.length; r++) {
      const room = rooms[r];
      const imgs = Array.isArray(room.images) ? room.images : [];
      let url = (imgs[0] && imgs[0].url) || room.image;
      if (!url && V) url = V.generateRoomSceneDataUrl(room, 0);
      ctxMedia.room[room.id] = await media(url, 1200, 750);
      const assets = room.assets || [];
      for (let k = 0; k < assets.length; k++) {
        let aUrl = assets[k].image;
        if (!aUrl && V) aUrl = V.generateAssetImageDataUrl(assets[k].name, assets[k]["function"], room.color);
        ctxMedia.asset[room.id + "|a|" + k] = await media(aUrl, 600, 380);
      }
      const staff = room.staff || [];
      for (let k = 0; k < staff.length; k++) {
        let sUrl = staff[k].customPhoto;
        if (!sUrl && V) sUrl = V.getStaffAvatarDataUrl(staff[k].avatar || "executive-chef");
        ctxMedia.staff[room.id + "|s|" + k] = await media(sUrl, 240, 240);
      }
    }

    const croquisSlideNum = (plan.findIndex(function (p) { return p.kind === "croquis"; }) + 1) || 3;

    const ctx = {
      info: info, rooms: rooms, zones: Array.isArray(data.structuralZones) ? data.structuralZones : [],
      exterior: exterior, media: ctxMedia, roomSlide: roomSlide, croquisSlide: croquisSlideNum, total: plan.length,
      totalAssets: rooms.reduce(function (a, r) { return a + (r.assets || []).length; }, 0),
      totalStaff: rooms.reduce(function (a, r) { return a + (r.staff || []).length; }, 0),
      capacity: parseCapacity(info.dailyCapacity || "25,000 وجبة يومياً"),
      categories: catNames.map(function (c) { return { name: c, rooms: catMap[c] }; }),
      brand: "مطبخ العزيزية المركزي — مبنى 52",
      footer: str(info.clientName, "مشروع مطبخ العزيزية المركزي - مبنى 52")
    };

    // بناء الشرائح
    const slides = plan.map(function (p, i) {
      const s = new SlideBuilder(i + 1);
      switch (p.kind) {
        case "cover": slideCover(s, ctx); break;
        case "exterior": slideExteriorGallery(s, ctx, p.idx); break;
        case "overview": slideOverview(s, ctx); break;
        case "croquis": slideCroquis(s, ctx); break;
        case "evacuation": slideEvacuation(s, ctx); break;
        case "room": slideRoom(s, ctx, p.room, p.idx); break;
        case "assets": slideAssets(s, ctx, p.room, p.idx, p.list, p.page, p.pages); break;
        case "staff": slideStaff(s, ctx, p.room, p.idx, p.list, p.page, p.pages); break;
        case "closing": slideClosing(s, ctx); break;
      }
      return s;
    });

    // ملاحظات المتحدث
    let notesCount = 0;
    slides.forEach(function (s) {
      if (!s.notes) return;
      notesCount++;
      s.notesIndex = notesCount;
      s.rel("notesSlide", "../notesSlides/notesSlide" + notesCount + ".xml");
      files.push({ name: "ppt/notesSlides/notesSlide" + notesCount + ".xml", data: notesSlideXml(s.notes) });
      files.push({
        name: "ppt/notesSlides/_rels/notesSlide" + notesCount + ".xml.rels",
        data: XML_HEAD + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
          '<Relationship Id="rId1" Type="' + REL + 'notesMaster" Target="../notesMasters/notesMaster1.xml"/>' +
          '<Relationship Id="rId2" Type="' + REL + 'slide" Target="../slides/slide' + s.index + '.xml"/></Relationships>'
      });
    });

    slides.forEach(function (s) {
      files.push({ name: "ppt/slides/slide" + s.index + ".xml", data: s.toXml() });
      files.push({ name: "ppt/slides/_rels/slide" + s.index + ".xml.rels", data: s.relsXml() });
    });

    // الأجزاء الثابتة
    const ct = XML_HEAD + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
      '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
      '<Default Extension="xml" ContentType="application/xml"/>' +
      '<Default Extension="jpg" ContentType="image/jpeg"/>' +
      '<Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>' +
      '<Override PartName="/ppt/presProps.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presProps+xml"/>' +
      '<Override PartName="/ppt/viewProps.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.viewProps+xml"/>' +
      '<Override PartName="/ppt/tableStyles.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.tableStyles+xml"/>' +
      '<Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>' +
      '<Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>' +
      '<Override PartName="/ppt/notesMasters/notesMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.notesMaster+xml"/>' +
      '<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>' +
      '<Override PartName="/ppt/theme/theme2.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>' +
      '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>' +
      '<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>' +
      slides.map(function (s) { return '<Override PartName="/ppt/slides/slide' + s.index + '.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>'; }).join("") +
      slides.filter(function (s) { return s.notesIndex; }).map(function (s) { return '<Override PartName="/ppt/notesSlides/notesSlide' + s.notesIndex + '.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.notesSlide+xml"/>'; }).join("") +
      "</Types>";

    const rels = function (list) {
      return XML_HEAD + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        list.map(function (r) { return '<Relationship Id="' + r[0] + '" Type="' + r[1] + '" Target="' + r[2] + '"/>'; }).join("") + "</Relationships>";
    };

    const now = new Date().toISOString().replace(/\.\d+Z$/, "Z");
    const pkgFiles = [
      { name: "[Content_Types].xml", data: ct },
      { name: "_rels/.rels", data: rels([
        ["rId1", REL + "officeDocument", "ppt/presentation.xml"],
        ["rId2", "http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties", "docProps/core.xml"],
        ["rId3", REL + "extended-properties", "docProps/app.xml"]]) },
      { name: "docProps/core.xml", data: XML_HEAD + '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">' +
        "<dc:title>" + xmlEscape(str(info.title, "مطبخ العزيزية المركزي 52")) + "</dc:title><dc:creator>" + xmlEscape(str(info.clientName, "")) + "</dc:creator><dc:language>ar-SA</dc:language>" +
        '<dcterms:created xsi:type="dcterms:W3CDTF">' + now + '</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">' + now + "</dcterms:modified></cp:coreProperties>" },
      { name: "docProps/app.xml", data: XML_HEAD + '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>Microsoft Office PowerPoint</Application><Slides>' + slides.length + "</Slides><Notes>" + notesCount + "</Notes></Properties>" },
      { name: "ppt/presentation.xml", data: XML_HEAD + "<p:presentation " + NS + ' saveSubsetFonts="1" rtl="1">' +
        '<p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rIdM1"/></p:sldMasterIdLst>' +
        '<p:notesMasterIdLst><p:notesMasterId r:id="rIdN1"/></p:notesMasterIdLst>' +
        "<p:sldIdLst>" + slides.map(function (s) { return '<p:sldId id="' + (255 + s.index) + '" r:id="rIdS' + s.index + '"/>'; }).join("") + "</p:sldIdLst>" +
        '<p:sldSz cx="' + SLD_W + '" cy="' + SLD_H + '"/><p:notesSz cx="6858000" cy="9144000"/>' +
        '<p:defaultTextStyle><a:lvl1pPr algn="r" rtl="1"><a:defRPr lang="ar-SA" sz="1400"><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:defRPr></a:lvl1pPr></p:defaultTextStyle>' +
        "</p:presentation>" },
      { name: "ppt/_rels/presentation.xml.rels", data: rels([
        ["rIdM1", REL + "slideMaster", "slideMasters/slideMaster1.xml"],
        ["rIdN1", REL + "notesMaster", "notesMasters/notesMaster1.xml"],
        ["rIdT1", REL + "theme", "theme/theme1.xml"],
        ["rIdP1", REL + "presProps", "presProps.xml"],
        ["rIdV1", REL + "viewProps", "viewProps.xml"],
        ["rIdTS1", REL + "tableStyles", "tableStyles.xml"]
      ].concat(slides.map(function (s) { return ["rIdS" + s.index, REL + "slide", "slides/slide" + s.index + ".xml"]; }))) },
      { name: "ppt/presProps.xml", data: XML_HEAD + "<p:presentationPr " + NS + "/>" },
      { name: "ppt/viewProps.xml", data: XML_HEAD + "<p:viewPr " + NS + '><p:normalViewPr><p:restoredLeft sz="15620"/><p:restoredTop sz="94660"/></p:normalViewPr><p:gridSpacing cx="76200" cy="76200"/></p:viewPr>' },
      { name: "ppt/tableStyles.xml", data: XML_HEAD + '<a:tblStyleLst xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" def="{5C22544A-7EE6-4342-B048-85BDC9FD1C3A}"/>' },
      { name: "ppt/slideMasters/slideMaster1.xml", data: XML_HEAD + "<p:sldMaster " + NS + '><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="' + C.bg + '"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree>' + GRP + "</p:spTree></p:cSld>" +
        CLRMAP + '<p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst>' +
        '<p:txStyles><p:titleStyle><a:lvl1pPr algn="r" rtl="1"><a:defRPr sz="2800" b="1"><a:solidFill><a:srgbClr val="' + C.navy700 + '"/></a:solidFill><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:defRPr></a:lvl1pPr></p:titleStyle>' +
        '<p:bodyStyle><a:lvl1pPr algn="r" rtl="1"><a:defRPr sz="1400"><a:solidFill><a:srgbClr val="' + C.ink + '"/></a:solidFill><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:defRPr></a:lvl1pPr></p:bodyStyle>' +
        '<p:otherStyle><a:lvl1pPr algn="r" rtl="1"><a:defRPr sz="1400"><a:latin typeface="' + FONT + '"/><a:cs typeface="' + FONT + '"/></a:defRPr></a:lvl1pPr></p:otherStyle></p:txStyles></p:sldMaster>' },
      { name: "ppt/slideMasters/_rels/slideMaster1.xml.rels", data: rels([
        ["rId1", REL + "slideLayout", "../slideLayouts/slideLayout1.xml"],
        ["rId2", REL + "theme", "../theme/theme1.xml"]]) },
      { name: "ppt/slideLayouts/slideLayout1.xml", data: XML_HEAD + "<p:sldLayout " + NS + ' type="blank" preserve="1"><p:cSld name="Blank"><p:spTree>' + GRP + "</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>" },
      { name: "ppt/slideLayouts/_rels/slideLayout1.xml.rels", data: rels([["rId1", REL + "slideMaster", "../slideMasters/slideMaster1.xml"]]) },
      { name: "ppt/notesMasters/notesMaster1.xml", data: notesMasterXml() },
      { name: "ppt/notesMasters/_rels/notesMaster1.xml.rels", data: rels([["rId1", REL + "theme", "../theme/theme2.xml"]]) },
      { name: "ppt/theme/theme1.xml", data: themeXml("Aziziyah52") },
      { name: "ppt/theme/theme2.xml", data: themeXml("Aziziyah52Notes") }
    ];

    const blob = createZipBlob(pkgFiles.concat(files));
    return { blob: blob, slideCount: slides.length, notesCount: notesCount };
  }

  async function exportPresentationToPptx(kitchenData) {
    const result = await buildPptx(kitchenData);
    const downloadUrl = URL.createObjectURL(result.blob);
    const a = document.createElement("a");
    a.href = downloadUrl;
    a.download = "العرض_التقديمي_مطبخ_العزيزية_المركزي_52.pptx";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(downloadUrl); }, 5000);
    return result;
  }

  return {
    buildPptx: buildPptx,
    exportPresentationToPptx: exportPresentationToPptx,
    // مكشوفة للاختبارات
    _maintenanceInfo: maintenanceInfo,
    _fitText: fitText
  };
})();
